package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0.00 or more, with up to two decimals. */
    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> body) throws InvalidSheetException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        boolean floor = SettingStore.FLOOR.equals(key);
        boolean terms = SettingStore.TERMS.equals(key);
        boolean gradeTerms = key.startsWith(SettingStore.TERMS_PREFIX)
                && SettingStore.GRADES.contains(key.substring(SettingStore.TERMS_PREFIX.length()));
        boolean late = SettingStore.LATE_PCT.equals(key);
        boolean numbering = SettingStore.PERIOD_NUMBERING_FROM.equals(key);
        boolean dated = SettingStore.POLICY_DATE.equals(key) || numbering;
        boolean cap = SettingStore.CAP.equals(key);
        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !floor && !terms && !gradeTerms && !late && !dated) {
            throw new InvalidSheetException("Not a setting: " + key);
        }
        String value = request.value() == null ? "" : request.value().trim();
        String fromValue = request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!dated && !fromValue.isEmpty()) {
            try {
                from = LocalDate.parse(fromValue);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
            }
        }
        if (dated) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            try {
                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
            } catch (DateTimeParseException e) {
                throw new InvalidSheetException((numbering ? "The period numbering from" : "The policy date")
                        + " must be a date (YYYY-MM-DD), or blank");
            }
            return;
        }
        if (gradeTerms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (terms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (value.isEmpty() && floor) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), from, request.user()));
            return;
        }
        if (value.isEmpty() && late) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
            return;
        }
        if (value.isEmpty()) {
            body.set(new SettingInput(key, null, from, request.user()));
            return;
        }
        if (!LIMIT.matcher(value).matches()) {
            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
                    : late ? "The late percent must be 0.00 or more with up to two decimals"
                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
        }
        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
    }
}
-- The roles the sheet assigns: a user name with no row here is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(32)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's settings, by key; a null value is blank (for clerk-limit: no limit). A key with no
-- row here has never been set.
CREATE TABLE sheet_setting (
    sheet_id    VARCHAR(255) NOT NULL,
    setting_key VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key)
);
-- The settings that carry a figure are dated: each value is recorded from a from-date, and the value in
-- force on a date is the one with the latest from-date on or before it (before every from-date, the
-- sheet's starting value). A null value is blank (for clerk-limit and cap: none; for a grade's terms:
-- the sheet's). The policy date and the period numbering date stay undated in sheet_setting.
CREATE TABLE sheet_setting_from (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- A value set before settings were dated holds from the start.
INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
    WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Settings, settingsKey, useSettings } from './settings';

type Key = 'clerk-limit' | 'floor' | 'terms' | 'terms-A' | 'terms-B' | 'terms-C' | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'cap';

const GRADES = ['A', 'B', 'C'] as const;

/** The settings that carry a figure: each is saved from a from-date (blank for the sheet's today). */
type DatedKey = Exclude<Key, 'policy-date' | 'period-numbering-from'>;

const NO_FROM: Record<DatedKey, string> = { 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'late-pct': '', cap: '' };

const isDated = (k: Key): k is DatedKey => k in NO_FROM;

// The sheet's settings in force, and the form that changes them: the clerk limit (blank for none),
// the floor (blank for its default), the terms in days (blank for 14), each grade's own terms (blank
// for the sheet's terms) and the late percent (blank for
// 0.00), the policy date rounding turns on (blank for the sheet's today) and the date claims opened
// are numbered per period from (blank for off), and the cap on a person's due-total (blank for none). Saving changes the setting last touched, so a field left blank does not clear the others.
// Each setting that carries a figure is saved from its from-date (blank for the sheet's today), and shows
// the value in force on the sheet's today; the policy date and period numbering date are not dated.
function SheetSettings() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const settings = useSettings(sheet);
  const [values, setValues] = useState<Record<Key, string>>({ 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', cap: '' });
  const [froms, setFroms] = useState<Record<DatedKey, string>>(NO_FROM);
  const [key, setKey] = useState<Key>('clerk-limit');
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: ({ key, value, from }: { key: Key; value: string; from: string }) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { key, value, from, user }),
    onSuccess: async (_, { key }) => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
      setValues((v) => ({ ...v, [key]: '' }));
      if (isDated(key)) setFroms((f) => ({ ...f, [key]: '' }));
    },
  });
  const submit = useSubmitOnce(save);

  const field = (k: Key, placeholder: string, inputMode: 'decimal' | 'text' = 'decimal') => (
    <input
      data-testid={`setting-${k}`}
      placeholder={placeholder}
      inputMode={inputMode}
      value={values[k]}
      onFocus={() => setKey(k)}
      onChange={(e) => {
        setValues({ ...values, [k]: e.target.value });
        setKey(k);
        save.reset();
      }}
    />
  );

  const from = (k: DatedKey) => (
    <input
      data-testid={`setting-${k}-from`}
      placeholder="From YYYY-MM-DD (blank for today)"
      value={froms[k]}
      onFocus={() => setKey(k)}
      onChange={(e) => {
        setFroms({ ...froms, [k]: e.target.value });
        setKey(k);
        save.reset();
      }}
    />
  );

  return (
    <section data-testid="settings">
      <h2>Settings</h2>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ key, value: values[key], from: isDated(key) ? froms[key] : '' });
        }}
      >
        Clerk limit <strong data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</strong>{' '}
        {field('clerk-limit', 'Clerk limit (blank for none)')}{' '}{from('clerk-limit')}{' '}
        Floor <strong data-testid="setting-floor-current">{settings.data?.floor ?? ''}</strong>{' '}
        {field('floor', 'Floor (blank for 1.00)')}{' '}{from('floor')}{' '}
        Terms <strong data-testid="setting-terms-current">{settings.data?.terms ?? ''}</strong>{' '}
        {field('terms', 'Terms in days (blank for 14)')}{' '}{from('terms')}{' '}
        {GRADES.map((g) => (
          <span key={g}>
            Terms {g} <strong data-testid={`setting-terms-${g}-current`}>{settings.data?.gradeTerms?.[g] ?? ''}</strong>{' '}
            {field(`terms-${g}`, `Terms for grade ${g} (blank for the sheet's)`)}{' '}{from(`terms-${g}`)}{' '}
          </span>
        ))}
        Late percent <strong data-testid="setting-late-pct-current">{settings.data?.latePct ?? ''}</strong>{' '}
        {field('late-pct', 'Late percent (blank for 0.00)')}{' '}{from('late-pct')}{' '}
        Policy date <strong data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</strong>{' '}
        {field('policy-date', 'Policy date YYYY-MM-DD (blank for today)', 'text')}{' '}
        Period numbering from <strong data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</strong>{' '}
        {field('period-numbering-from', 'Period numbering from YYYY-MM-DD (blank for off)', 'text')}{' '}
        Cap <strong data-testid="setting-cap-current">{settings.data?.cap ?? ''}</strong>{' '}
        {field('cap', 'Cap (blank for none)')}{' '}{from('cap')}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The settings were refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

