cat > $C/ApplyProof.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one; refused for a SETTLED or VOID claim, or when another user moved it on first. */
public class ApplyProof {
    public void apply(@Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID || !store.addProof(claim)) {
            throw new InvalidSheetException("A proof cannot be added to a " + claim.getStatus() + " claim");
        }
    }
}
EOF
cat > $C/AuditClaimProof.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored proof: CLAIM_PROOF_ADDED sheet=<id> by=<user> person=<name> amount=<0.00>
 *  date=<yyyy-mm-dd>, then number=<n> when the claim has one, then proofs=<count>. */
public class AuditClaimProof {
    public void audit(@Val ProofInput input, @Val Claim claim, PersonStore people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_PROOF_ADDED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber())
                + " proofs=" + claim.getProofs());
    }
}
EOF
cat > "resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/proof.POST.yml" <<'EOF'
# POST /api/sheets/{sheetId}/claims/{claimId}/proof — raise a claim's proofs count by one (body {user}).
# Refused (400) for a SETTLED or VOID claim, a claim not on the sheet, or one whose date falls in a
# closed period; nothing is stored then. A stored proof is recorded in the audit file as CLAIM_PROOF_ADDED.
validate:
  class: net.officefloor.hq.app.claim.ValidateProof
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyProof
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimProof
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
EOF

